47: // which can be called for both outbound and inbound cluster, but only connection pool will be applied to inbound cluster.
48: func (cb *ClusterBuilder) applyTrafficPolicy(service *model.Service, opts buildClusterOpts) {
49: 	connectionPool, outlierDetection, loadBalancer, tls, proxyProtocol, retryBudget := selectTrafficPolicyComponents(opts.policy)
50: 	// Connection pool settings are applicable for both inbound and outbound clusters.
51: 	if connectionPool == nil {
52: 		connectionPool = &networking.ConnectionPoolSettings{}
53: 	}
54: 	// Apply h2 upgrade s.t. h2 connection pool settings can be applied to the cluster.
55: 	if opts.direction != model.TrafficDirectionInbound {
56: 		cb.applyH2Upgrade(opts.mutable, opts.port, opts.mesh, connectionPool)
57: 	}
58: 	cb.applyConnectionPool(opts.mesh, opts.mutable, connectionPool, retryBudget)
59: 	if opts.direction != model.TrafficDirectionInbound {
60: 		applyOutlierDetection(service, opts.mutable.cluster, outlierDetection)
61: 		if outlierDetection != nil && len(outlierDetection.OutlierDetectionHttpErrorCodes) > 0 {
62: 			applyOutlierDetectionErrorCodes(opts.mutable, outlierDetection.OutlierDetectionHttpErrorCodes)
63: 		}
64: 		enableSelfDiscovery := cb.proxyMetadata != nil && bool(cb.proxyMetadata.EnableSelfDiscovery)
65: 		applyLoadBalancer(
66: 			service, opts.mutable.cluster, loadBalancer, opts.port, cb.locality,
67: 			cb.proxyLabels, opts.mesh, opts.mutable.dnsWrappedLocalityLbEndpoints,
